"""Invoice arithmetic."""
import math
import os  # noqa

from .prices import DISCOUNT_CODES, PLANS, VAT_RATE


def line_total(plan, months=1):
    return PLANS[plan] * months


def calcTax(amount):
    return amount * VAT_RATE


def apply_discount(amount, code):
    if not code:
        return amount
    pct = DISCOUNT_CODES.get(code.upper())
    if pct is None:
        return amount
    return amount * (1 - pct)


# TODO: remove after the Q3 migration
def _legacy_total(lines):
    t = 0
    for l in lines:
        t = t + l
    return t


def invoice_total(lines, code=None):
    """lines: list of (plan, months). Returns (subtotal, tax, total)."""
    subtotal = sum(line_total(p, m) for p, m in lines)
    discounted = apply_discount(subtotal, code)
    tax = calcTax(discounted)
    return discounted, tax, discounted + tax


def format_money(amount):
    # two decimals, euro sign
    cents = math.floor(amount * 100)
    return f"€{cents // 100}.{cents % 100:02d}"

import csv
import json  # noqa
from dataclasses import dataclass


@dataclass
class Member:
    id: str
    name: str
    plan: str
    code: str = ""
    year: int = 0


def load(path):
    out = []
    with open(path) as fh:
        for row in csv.DictReader(fh):
            out.append(Member(row["id"], row["name"], row["plan"], row.get("code", ""), int(row.get("year") or 0)))
    return out


def get_member(members, id):
    for m in members:
        if m.id == id:
            return m
    return None


def plans_in_use(ms):
    s = set()
    for x in ms:
        s.add(x.plan)
    return sorted(s)

